import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Mic, Square, Bell, Check, Settings, Play, Pause, RefreshCw, Trash2, Heart, Star, Send } from 'lucide-react';

function ComponentShowcase() {
  const [toggle, setToggle] = useState(false);
  const [activeTab, setActiveTab] = useState('buttons');

  return (
    <div className="bg-gray-800 rounded-xl shadow-2xl p-8 w-full max-w-4xl animate-fade-in">
      <div className="flex justify-between items-center mb-8 border-b border-gray-700 pb-4">
        <h2 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500">
          UI Component Gallery
        </h2>
        <div className="flex space-x-2">
          {['buttons', 'switches', 'animations'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 rounded-lg capitalize transition-all duration-300 ${
                activeTab === tab 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/50' 
                  : 'text-gray-400 hover:text-white hover:bg-gray-700'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-8">
        {activeTab === 'buttons' && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <button className="flex items-center justify-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white p-3 rounded-lg transition-transform hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20">
              <Send size={18} /> <span>Primary</span>
            </button>
            <button className="flex items-center justify-center space-x-2 bg-purple-600 hover:bg-purple-700 text-white p-3 rounded-lg transition-transform hover:scale-105 active:scale-95 shadow-lg shadow-purple-500/20">
              <Star size={18} /> <span>Secondary</span>
            </button>
            <button className="flex items-center justify-center space-x-2 bg-emerald-600 hover:bg-emerald-700 text-white p-3 rounded-lg transition-transform hover:scale-105 active:scale-95 shadow-lg shadow-emerald-500/20">
              <Check size={18} /> <span>Success</span>
            </button>
            <button className="flex items-center justify-center space-x-2 bg-rose-600 hover:bg-rose-700 text-white p-3 rounded-lg transition-transform hover:scale-105 active:scale-95 shadow-lg shadow-rose-500/20">
              <Trash2 size={18} /> <span>Danger</span>
            </button>
          </div>
        )}

        {activeTab === 'switches' && (
          <div className="flex flex-col space-y-6 items-center py-4">
            <div className="flex items-center space-x-4">
              <span className="text-gray-300">Default Toggle</span>
              <button 
                onClick={() => setToggle(!toggle)}
                className={`relative w-14 h-7 rounded-full transition-colors duration-300 ${toggle ? 'bg-blue-600' : 'bg-gray-600'}`}
              >
                <div className={`absolute top-1 left-1 w-5 h-5 bg-white rounded-full transition-transform duration-300 ${toggle ? 'translate-x-7' : 'translate-x-0'}`} />
              </button>
            </div>

            <div className="flex items-center space-x-4">
              <span className="text-gray-300">Icon Switch</span>
              <div 
                onClick={() => setToggle(!toggle)}
                className="flex bg-gray-700 p-1 rounded-xl cursor-pointer"
              >
                <div className={`p-2 rounded-lg transition-all ${!toggle ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>
                  <Play size={20} />
                </div>
                <div className={`p-2 rounded-lg transition-all ${toggle ? 'bg-purple-600 text-white shadow-md' : 'text-gray-400'}`}>
                  <Pause size={20} />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'animations' && (
          <div className="grid grid-cols-2 gap-8 items-center justify-items-center py-4">
            <div className="p-8 bg-gray-700 rounded-full animate-spin-slow">
              <RefreshCw size={48} className="text-blue-400" />
            </div>
            <div className="p-8 bg-gray-700 rounded-full animate-bounce">
              <Heart size={48} className="text-rose-500 fill-rose-500" />
            </div>
            <div className="p-8 bg-gray-700 rounded-2xl animate-pulse">
              <Bell size={48} className="text-yellow-400" />
            </div>
            <div className="group relative cursor-pointer">
              <div className="absolute -inset-1 bg-gradient-to-r from-pink-600 to-purple-600 rounded-lg blur opacity-25 group-hover:opacity-100 transition duration-1000 group-hover:duration-200"></div>
              <div className="relative px-7 py-4 bg-gray-800 rounded-lg leading-none flex items-center divide-x divide-gray-600">
                <span className="flex items-center space-x-5">
                  <Settings className="text-indigo-400 group-hover:rotate-90 transition-transform duration-500" size={24} />
                  <span className="pr-6 text-gray-100">Hover for Glow</span>
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function App() {
  const [view, setView] = useState('voice');
  const [status, setStatus] = useState('idle');
  const [transcript, setTranscript] = useState('');
  const [reply, setReply] = useState('');
  const [error, setError] = useState('');
  const [sessionId] = useState(() => Math.random().toString(36).slice(2));

  const recognitionRef = useRef(null);
  const isSpeechApiAvailable = useMemo(() => {
    return Boolean(window.SpeechRecognition || window.webkitSpeechRecognition);
  }, []);

  useEffect(() => {
    if (!isSpeechApiAvailable) return;

    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const rec = new Recognition();
    rec.continuous = false;
    rec.interimResults = true;
    rec.lang = 'en-US';

    rec.onstart = () => {
      setError('');
      setStatus('listening');
    };

    rec.onresult = (event) => {
      let finalText = '';
      let interimText = '';
      for (let i = event.resultIndex; i < event.results.length; i += 1) {
        const res = event.results[i];
        const txt = res[0]?.transcript || '';
        if (res.isFinal) finalText += txt;
        else interimText += txt;
      }
      setTranscript((finalText || interimText).trim());
    };

    rec.onerror = (e) => {
      setStatus('idle');
      setError(e?.error ? `Speech error: ${e.error}` : 'Speech recognition error');
    };

    rec.onend = () => {
      setStatus((s) => (s === 'listening' ? 'thinking' : s));
    };

    recognitionRef.current = rec;
  }, [isSpeechApiAvailable]);

  const speak = (text) => {
    try {
      window.speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.rate = 1.02;
      u.pitch = 1.0;
      u.onstart = () => setStatus('speaking');
      u.onend = () => setStatus('idle');
      window.speechSynthesis.speak(u);
    } catch (e) {
      setStatus('idle');
      setError('TTS failed in this browser');
    }
  };

  const startListening = async () => {
    setError('');
    setReply('');
    setTranscript('');

    if (!isSpeechApiAvailable) {
      setError('SpeechRecognition is not supported in this browser. Try Chrome/Edge.');
      return;
    }
    recognitionRef.current?.start();
  };

  const stopListening = () => {
    try {
      recognitionRef.current?.stop();
    } catch {
      // ignore
    }
  };

  const sendToBackend = async () => {
    const text = (transcript || '').trim();
    if (!text) {
      setError('Say something first, then try again.');
      return;
    }
    setStatus('thinking');
    setError('');

    try {
      const res = await fetch('http://127.0.0.1:8000/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_id: sessionId, text }),
      });
      if (!res.ok) {
        setStatus('idle');
        setError(`Backend error (${res.status})`);
        return;
      }
      const data = await res.json();
      const r = (data?.reply || '').toString();
      setReply(r);
      speak(r);
    } catch (e) {
      setStatus('idle');
      setError('Failed to reach backend. Is it running on 127.0.0.1:8000?');
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 space-y-8">
      {/* Navigation Toggle */}
      <div className="flex bg-gray-800 p-1 rounded-2xl border border-gray-700 shadow-xl">
        <button 
          onClick={() => setView('voice')}
          className={`flex items-center space-x-2 px-6 py-2 rounded-xl transition-all duration-300 ${
            view === 'voice' 
              ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-lg' 
              : 'text-gray-400 hover:text-white'
          }`}
        >
          <Mic size={18} /> <span>Recorder</span>
        </button>
        <button 
          onClick={() => setView('showcase')}
          className={`flex items-center space-x-2 px-6 py-2 rounded-xl transition-all duration-300 ${
            view === 'showcase' 
              ? 'bg-gradient-to-r from-purple-600 to-purple-500 text-white shadow-lg' 
              : 'text-gray-400 hover:text-white'
          }`}
        >
          <Settings size={18} /> <span>UI Showcase</span>
        </button>
      </div>

      {view === 'voice' ? (
        <div className="bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl shadow-2xl p-8 max-w-2xl w-full mx-auto transform hover:scale-[1.01] transition-transform duration-500">
          <h1 className="text-white text-4xl font-black text-center mb-2 tracking-tight">VocalFlow</h1>
          <div className="text-center text-blue-100/90 text-sm font-medium mb-6">Local voice agent (no downloads)</div>

          <div className="flex flex-col gap-3 mb-6">
            <div className="bg-white/10 border border-white/15 rounded-2xl p-4">
              <div className="text-white/80 text-xs font-semibold mb-2">YOU SAID</div>
              <div className="text-white text-lg font-semibold min-h-[28px]">{transcript || '—'}</div>
            </div>
            <div className="bg-white/10 border border-white/15 rounded-2xl p-4">
              <div className="text-white/80 text-xs font-semibold mb-2">AGENT REPLY</div>
              <div className="text-white text-lg font-semibold min-h-[28px]">{reply || '—'}</div>
            </div>
            {error ? (
              <div className="bg-rose-500/20 border border-rose-300/30 text-rose-50 rounded-2xl p-3 text-sm">
                {error}
              </div>
            ) : null}
          </div>

          <p className={`text-center text-xl font-medium mb-6 ${status === 'idle' ? 'text-blue-100' : status === 'listening' ? 'text-yellow-200 animate-pulse' : status === 'thinking' ? 'text-blue-200' : 'text-purple-200 animate-bounce'}`}>
            {status.toUpperCase()}
          </p>

          <div className="flex flex-wrap justify-center gap-3">
            <button
              onClick={startListening}
              disabled={status !== 'idle'}
              className="group bg-white hover:bg-blue-50 disabled:bg-gray-200 text-blue-600 font-bold py-3 px-6 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center active:scale-95"
            >
              <Mic className={`mr-2 transition-transform duration-300 group-hover:scale-110 ${status === 'listening' ? 'animate-pulse' : ''}`} />
              Talk
            </button>

            <button
              onClick={stopListening}
              disabled={status !== 'listening'}
              className="group bg-red-500 hover:bg-red-600 disabled:bg-gray-200 text-white font-bold py-3 px-6 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center active:scale-95"
            >
              <Square className="mr-2 transition-transform duration-300 group-hover:scale-110" />
              Stop
            </button>

            <button
              onClick={sendToBackend}
              disabled={status !== 'thinking' && status !== 'idle'}
              className="group bg-slate-900/40 hover:bg-slate-900/55 disabled:bg-gray-200 text-white font-bold py-3 px-6 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center active:scale-95 border border-white/15"
            >
              <Send className="mr-2" />
              Ask Agent
            </button>
          </div>

          {!isSpeechApiAvailable ? (
            <div className="mt-6 text-center text-white/80 text-sm">
              SpeechRecognition not available. Try Chrome or Edge.
            </div>
          ) : null}
        </div>
      ) : (
        <ComponentShowcase />
      )}

      {/* Footer Info */}
      <div className="text-gray-500 text-sm font-medium">
        Made with Heaven &bull; React &bull; Tailwind &bull; Lucide
      </div>
    </div>
  );
}

export default App;
